plugins {
    id("kmongo-dsl.kotlin-serialization")
    id("org.jetbrains.kotlin.kapt")
}

description = "Tests of the KMongo DSL KAPT annotation processor (not published)"

// the tests (and the models) of the KSP processor are run against the code generated by the KAPT processor
val kspTestSources = project(":kmongo-dsl-ksp-test").layout.projectDirectory.dir("src/test")
sourceSets.test {
    kotlin.srcDir(kspTestSources.dir("kotlin"))
    resources.srcDir(kspTestSources.dir("resources"))
}

dependencies {
    testImplementation(project(":kmongo-dsl-core"))
    testImplementation(project(":kmongo-dsl-test"))
    testImplementation(project(":kmongo-dsl-jackson-mapping"))
    testImplementation(project(":kmongo-dsl-jackson-data"))
    kaptTest(project(":kmongo-dsl-annotation-processor"))
}

// the KAPT and KSP processors must generate the same code
val kspGenerated = project(":kmongo-dsl-ksp-test").layout.buildDirectory.dir("generated/ksp/test/kotlin")
val kaptGenerated = layout.buildDirectory.dir("generated/source/kaptKotlin/test")
tasks.test {
    dependsOn(":kmongo-dsl-ksp-test:kspTestKotlin")
    inputs.dir(kspGenerated)
    systemProperty("kmongo.ksp.generated", kspGenerated.get().asFile.absolutePath)
    systemProperty("kmongo.kapt.generated", kaptGenerated.get().asFile.absolutePath)
}
